   Controls.Add(new Label{Text="Publicación de GitHub · usuario/repositorio",Bounds=new Rectangle(22,22,495,26)});repo=new TextBox{Text=r,Bounds=new Rectangle(22,53,495,27)};Controls.Add(repo);Controls.Add(new Label{Text="Solo el creador configura la publicación. Tus amigos reciben\nel launcher listo para descargar y actualizar el paquete.",Bounds=new Rectangle(22,93,495,47),ForeColor=Color.Silver});Controls.Add(new Label{Text="Memoria de Minecraft (MB)",Bounds=new Rectangle(22,159,290,27)});ram=new NumericUpDown{Minimum=2048,Maximum=12288,Increment=1024,Value=Math.Max(2048,Math.Min(12288,c.ram)),Bounds=new Rectangle(350,156,165,28)};Controls.Add(ram);var save=new Button{Text="Guardar",Bounds=new Rectangle(350,211,165,35)};save.Click+=delegate{try{Value=new Config{channel=String.IsNullOrWhiteSpace(repo.Text)?"":Engine.Channel(repo.Text.Trim()),ram=(int)ram.Value};DialogResult=DialogResult.OK;}catch(Exception e){MessageBox.Show(e.Message);}};Controls.Add(save);AcceptButton=save;
